mapper.select:
SELECT
  bbd.org_id AS orgId,
  bbd.executor_id AS dentistId,
  bbd.item_type AS itemType,
  bbd.item_id AS itemId,
  IFNULL(bbd.swipe_workload, 0) AS swipeWorkload,
  DATE_FORMAT(bbps.pay_date, '%Y%m%d') AS payDate,
  SUM(bbps.free_amount) AS freePaymentWorkload,
  SUM(bbps.received_amount) AS receivedWorkload
FROM base_bill_detail bbd
LEFT JOIN base_bill_pay_share bbps ON bbps.bill_detail_id=bbd.bill_detail_id

  bbd.executor_id > 0

    AND DATE_FORMAT(bbps.pay_date, '%Y-%m-%d') >= #{startDate}


    AND DATE_FORMAT(bbps.pay_date, '%Y-%m-%d') <= #{endDate}


    AND bbd.org_id = #{orgId}


    AND bbd.executor_id = #{executorId}


    AND bbd.item_type = #{itemType}


    AND bbd.item_id = #{itemId}


GROUP BY bbd.org_id, bbd.executor_id, bbps.item_type, bbps.item_id, DATE_FORMAT(bbps.pay_date, '%Y%m%d')
